files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --correct: #4ecca3;
  --wrong: #e94560;
  --pixel: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  padding: 32px 24px;
  border: var(--pixel) solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 420px;
  text-align: center;
}

.title {
  font-size: 28px;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.question {
  font-size: 24px;
  margin-bottom: 24px;
  min-height: 32px;
  font-weight: bold;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.answer,
.btn {
  font-family: inherit;
  font-size: 20px;
  padding: 12px 28px;
  background: var(--bg);
  color: var(--text);
  border: var(--pixel) solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
}

.answer:hover:not(:disabled),
.btn:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

.answer:focus-visible,
.btn:focus-visible {
  outline: var(--pixel) solid var(--accent-hover);
  outline-offset: 2px;
}

.answer:active:not(:disabled),
.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.answer:disabled,
.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.answer.correct {
  background: var(--correct);
  color: var(--bg);
  border-color: var(--correct);
}

.answer.wrong {
  background: var(--wrong);
  color: var(--bg);
}

.score-line {
  font-size: 20px;
  margin-bottom: 24px;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

#next {
  background: var(--accent);
  color: var(--bg);
}

#next:hover:not(:disabled) {
  background: var(--accent-hover);
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .title { font-size: 22px; }
  .question { font-size: 20px; }
  .answer, .btn { font-size: 18px; padding: 10px 20px; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let answered = false;
let finished = false;

function render() {
  if (finished) {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
    return;
  }
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  nextBtn.disabled = true;
}

function handleAnswer(choice) {
  if (answered || finished) return;
  answered = true;
  const q = questions[current];
  const selected = choice === 'a' ? answerA : answerB;
  const other = choice === 'a' ? answerB : answerA;

  if (choice === q.correct) {
    score++;
    scoreEl.textContent = score;
    selected.classList.add('correct');
  } else {
    selected.classList.add('wrong');
    other.classList.add('correct');
  }
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!answered) return;
  if (current < questions.length - 1) {
    current++;
    answered = false;
    render();
  } else {
    finished = true;
    render();
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  answered = false;
  finished = false;
  scoreEl.textContent = '0';
  render();
});

render();
